sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // 1. Resolve agent: Find Priya, Marcus, or Elena
    var agentSysId = null;
    var u = new GlideRecord('sys_user');
    u.addQuery('user_name', 'IN', 'retail_agent_marcus,retail_agent_priya,retail_agent_elena');
    u.query();
    if (u.next()) {
        agentSysId = u.getUniqueValue();
    } else {
        agentSysId = gs.getUserID();
    }

    // 2. Resolve Escalation Desk Group
    var grpSysId = null;
    var g = new GlideRecord('sys_user_group');
    if (g.get('name', 'Retail Escalation Desk')) {
        grpSysId = g.getUniqueValue();
    }

    // 3. Update the complaint with the assigned agent
    var comp = new GlideRecord('x_1958581_retail_0_retail_complaint');
    if (comp.get(current.sys_id)) {
        if (grpSysId) comp.assignment_group = grpSysId;
        if (agentSysId) comp.assigned_to = agentSysId;
        comp.state = 2; // Work in Progress
        comp.update();
    }

    // 4. Create child Store Escalation Task linked to this complaint and agent
    var task = new GlideRecord('x_1958581_retail_0_store_esc_task');
    task.initialize();
    if (task.isValidField('parent')) {
        task.parent = current.sys_id;
    }
    if (task.isValidField('parent_complaint')) {
        task.parent_complaint = current.sys_id;
    }
    task.short_description = "Quarantine batch & store investigation for: " + (current.short_description || current.description || "Food Safety Issue");
    task.priority = 1;
    task.state = 1; // Open
    if (grpSysId) task.assignment_group = grpSysId;
    if (agentSysId) task.assigned_to = agentSysId;
    task.insert();
})(current, previous);
